  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Absolute bioavailability of the Molecule 1 IR tablet was 86.4% in volunteers vs IV under fed conditions, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Absolute bioavailability of niraparib 300 mg oral was 72.7% vs IV in cancer patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Absolute bioavailability of maraviroc 100 mg tablet was 22.9% vs IV in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All informative high-transferability molecules have strongest adult absolute bioavailability records above 20% (roughly 23-88%), including direct IV-comparison measurements; low pediatric/fed values are less transferable and do not overturn the high prediction.",
  "evidence_gaps": [
    "One record (C12) is qualitative ('good') and lacks a numeric F value.",
    "Some low values come from children or altered formulations (e.g., C07, C03, C45) and fed-state didanosine records (C27, C28), limiting their transferability.",
    "A didanosine record (C39) refers to ddA/ddl rather than didanosine, a provenance inconsistency."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

